        }
        self.allocator.free(self.shape);
        self.shape = try self.allocator.dupe(usize, new_shape);
    }

    pub fn add(self: *TensorCore, other: *const TensorCore) !void {
        if (!self.shapeMatches(other)) return error.ShapeMismatch;
        for (self.data, other.data) |*val, o| {
            val.* += o;
        }
    }

    pub fn mul(self: *TensorCore, other: *const TensorCore) !void {
        if (!self.shapeMatches(other)) return error.ShapeMismatch;
        for (self.data, other.data) |*val, o| {
            val.* *= o;
        }
    }

    pub fn matmul(self: *TensorCore, other: *const TensorCore) !TensorCore {
        if (self.shape.len != 2 or other.shape.len != 2) return error.NotMatrix;
        if (self.shape[1] != other.shape[0]) return error.InvalidDimensions;
        const rows = self.shape[0];
        const cols = other.shape[1];
        const inner = self.shape[1];
        var result = try TensorCore.init(self.allocator, &[_]usize{ rows, cols }, .f64);
        var i: usize = 0;
        while (i < rows) : (i += 1) {
            var j: usize = 0;
            while (j < cols) : (j += 1) {
                var sum: f64 = 0.0;
                var k: usize = 0;
                while (k < inner) : (k += 1) {
                    sum += self.data[i * inner + k] * other.data[k * cols + j];
                }
                result.data[i * cols + j] = sum;
            }
        }
        return result;
    }

    pub fn softmax(self: *TensorCore, axis: usize) !void {
        if (self.shape.len != 2) return error.Not2D;
        const rows = self.shape[0];
        const cols = self.shape[1];
        if (axis > 1) return error.InvalidAxis;
        if (axis == 0) {
            var j: usize = 0;
            while (j < cols) : (j += 1) {
                var max_val: f64 = -math.inf(f64);
                var i: usize = 0;
                while (i < rows) : (i += 1) {
                    const val = self.data[i * cols + j];
                    if (val > max_val) max_val = val;
                }
                var exp_sum: f64 = 0.0;
                i = 0;
                while (i < rows) : (i += 1) {
                    const shifted = self.data[i * cols + j] - max_val;
                    const exp_val = math.exp(shifted);
                    self.data[i * cols + j] = exp_val;
                    exp_sum += exp_val;
                }
                const inv_sum = 1.0 / exp_sum;
                i = 0;
                while (i < rows) : (i += 1) {
                    self.data[i * cols + j] *= inv_sum;
                }
            }
        } else {
            var i: usize = 0;
            while (i < rows) : (i += 1) {
                var max_val: f64 = -math.inf(f64);
                var j: usize = 0;
                while (j < cols) : (j += 1) {
                    const val = self.data[i * cols + j];
                    if (val > max_val) max_val = val;
                }
                var exp_sum: f64 = 0.0;
                j = 0;
                while (j < cols) : (j += 1) {
                    const shifted = self.data[i * cols + j] - max_val;
                    const exp_val = math.exp(shifted);
                    self.data[i * cols + j] = exp_val;
                    exp_sum += exp_val;
                }
                const inv_sum = 1.0 / exp_sum;
                j = 0;
                while (j < cols) : (j += 1) {
                    self.data[i * cols + j] *= inv_sum;
                }
            }
        }
    }

    pub fn argmax(self: *TensorCore, axis: usize) !TensorCore {
        if (self.shape.len != 2) return error.Not2D;
        const rows = self.shape[0];
        const cols = self.shape[1];
        var result_shape = [1]usize{undefined};
        if (axis == 0) {
            result_shape[0] = cols;
        } else {
            result_shape[0] = rows;
        }
        var result = try TensorCore.init(self.allocator, &result_shape, .f64);
        if (axis == 0) {
            var j: usize = 0;
            while (j < cols) : (j += 1) {
                var max_idx: usize = 0;
                var max_val = self.data[0 * cols + j];
                var i: usize = 1;
                while (i < rows) : (i += 1) {
                    const val = self.data[i * cols + j];
                    if (val > max_val) {
                        max_val = val;
                        max_idx = i;
                    }
                }
                result.data[j] = @floatFromInt(max_idx);
            }
        } else {
            var i: usize = 0;
            while (i < rows) : (i += 1) {
                var max_idx: usize = 0;
                var max_val = self.data[i * cols + 0];
                var j: usize = 1;
                while (j < cols) : (j += 1) {
                    const val = self.data[i * cols + j];
                    if (val > max_val) {
                        max_val = val;
                        max_idx = j;
                    }
                }
                result.data[i] = @floatFromInt(max_idx);
            }
        }
        return result;
    }

    pub fn integrateQSM(self: *TensorCore, synapse: f64, contexts: [][]const f64) !void {
        try self.qsm.multiplex(synapse, contexts);
        const interf = self.qsm.getInterference();
        for (self.data) |*val| {
            val.* += interf;
        }
    }

    pub fn applyMES(self: *TensorCore, cond: bool, input_str: []const u8) !void {
        self.mes.selfOverwrite(cond);
        const processed = try self.mes.process(input_str);
        defer self.allocator.free(processed);
        if (processed.len > 0) {
            self.data[0] = @floatFromInt(processed[0]);
        }
    }

    pub fn reflectEHM(self: *TensorCore, refl: []const u8) !void {
        try self.ehm.update(refl);
        const state = self.ehm.getState();
        for (self.data) |*val| {
            val.* *= state;
        }
    }

    pub fn adjustMXSI(self: *TensorCore, v: f64, t: f64) void {
        self.mxsi.compute(v, t);
        const cond = self.mxsi.getConductance();
        for (self.data) |*val| {
            val.* *= cond;
        }
    }

    pub fn phaseCPS(self: *TensorCore, thoughts: [][]const u8) !void {
        self.cps.clearThoughts();
        for (thoughts) |th| {
            try self.cps.addThought(th);
        }
        try self.cps.computeTopology();
        const topology = self.cps.getTopology();
        var i: usize = 0;
        while (i < topology.len and i < self.data.len) : (i += 1) {
            self.data[i] += topology[i].phase;
        }
    }

    fn shapeMatches(self: *const TensorCore, other: *const TensorCore) bool {
        if (self.shape.len != other.shape.len) return false;
        for (self.shape, other.shape) |s, o| {
            if (s != o) return false;
        }
        return true;
    }
};

